def caesar_shift(s, shift):
    result = []
    for ch in s:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            offset = ord(ch) - base
            new_offset = (offset + shift) % 26
            result.append(chr(base + new_offset))
        else:
            result.append(ch)
    return ''.join(result)
